#!/usr/bin/env node
// Regenerates src/esi/npcCorporationData.json from CCP's official Static Data Export (SDE).
//
// NPC corporations rarely change, so instead of relying on the ESI search endpoint (which does
// not reliably return NPC corporations), Evelyn bundles a trimmed dataset generated by this
// script. This is the same approach used for src/esi/blueprintData.json.
//
// This script is run automatically by `yarn generate-data` and by CI before packaging the
// app. It can also be run manually to update the bundled data:
//
//   node scripts/generate-npc-corporations.mjs
//
// It requires network access to developers.eveonline.com.
//
// Docs: https://developers.eveonline.com/docs/services/static-data/

import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { downloadSdeZip, extractYamlFile } from "./sde.mjs";

const OUTPUT_PATH = fileURLToPath(new URL("../src/esi/npcCorporationData.json", import.meta.url));

async function main() {
  const zipBuffer = await downloadSdeZip();

  // CCP dropped the `fsd/` directory prefix in a later SDE rework, so the current layout has
  // this file at the zip root; the prefixed path is kept as a fallback for older zips.
  const corporations = extractYamlFile(zipBuffer, [
    "npcCorporations.yaml",
    "fsd/npcCorporations.yaml",
  ]);

  const data = [];
  for (const [corporationIdStr, corporation] of Object.entries(corporations)) {
    if (corporation.deleted) continue;

    const name = corporation.name?.en;
    if (!name) continue;

    data.push({ corporationId: Number(corporationIdStr), name });
  }

  data.sort((a, b) => a.name.localeCompare(b.name));
  await writeFile(OUTPUT_PATH, JSON.stringify(data));

  console.log(`Wrote ${data.length} NPC corporations to ${OUTPUT_PATH}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
